import { test, expect } from '@playwright/test';

test.describe('Modal Dialog Responsiveness on Mobile Screens', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-dialog');
  });

  test('should display modal correctly and be responsive on mobile screen sizes', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 860 });

    // Open modal by clicking the button
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).toBeVisible();

    // Verify modal title is visible
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Verify close button is visible and accessible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify modal has correct mobile styling (e.g, full width)
    const modalWrapper = page.locator('[data-testid="modal-wrapper"]');
    const isFullWidth = await modalWrapper.evaluate((el) => window.getComputedStyle(el).width === '100%');
    expect(isFullWidth).toBe(true);

    // Verify modal has correct mobile padding
    const modalPadding = await modalWrapper.evaluate((el) => window.getComputedStyle(el).padding);
    expect(modalPadding).toContain('1rem');
  });

  test('should handle modal responsiveness when resizing from desktop to mobile', async ({ page }) => {
    // Set viewport to desktop size
    await page.setViewportSize({ width: 1200, height: 900 });

    // Open modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible on desktop
    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).toBeVisible();

    // Verify modal has desktop styling (e.g., max-width)
    const modalWrapper = page.locator('[data-testid="modal-wrapper"]');
    const isMaxWidthed = await modalWrapper.evaluate((el)) => window.getComputedStyle(el).maxWidth === '600px';
    expect(isMaxWidthed).toBe(true);

    // Resize viewport to mobile size
    await page.setViewportSize({ width: 375, height: 860 });

    // Verify modal is still visible after resize
    await expect(modalContainer).toBeVisible();

    // Verify modal has responsive mobile styling (full width)
    const isMobileWidth = await modalWrapper.evaluate((el)) => window.getComputedStyle(el).width === '100%';
    expect(isMobileWidth).toBe(true);

    // Verify modal content is still accessible and readable
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify close button is still functional
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();
    await expect(modalContainer).not.toBeVisible();
  });
});
